# --- 6.1절에서 말한 그것 ---

#   SQL 로는 두 방식을 구분할 수 없다

#   달라지는 것은 자바 코드다

# --- 자바 코드로 비교하면 ---

#   도메인 모델        서비스 10줄, 엔티티 메서드 6개
#   트랜잭션 스크립트   서비스 25줄, 엔티티 메서드 0개

#   총 줄 수는 비슷하다

# --- 재고 감소가 두 곳에서 필요해지면 ---

#   (도메인 모델)
#   item.removeStock(count)   -- 한 곳에 정의

#   (트랜잭션 스크립트)
#   OrderService.order 에 5줄
#   OrderService.어떤메서드 에 5줄

#   두 번째에서 검사를 빠뜨리면

item.setStockQuantity(item.getStockQuantity() - count);

#   Hibernate: update item set ... stock_quantity=? where item_id=?
#   binding parameter [3] as [INTEGER] - [-5]

select stock_quantity from item where item_id = 1;
#   -5

#   재고가 음수가 됐다

#   SQL 은 정상이다
#   DB 제약도 없다 (3.3절)

#   이것이 규칙을 한곳에 두는 이유다

